        assert_eq!(super::ARCANE_ARTISAN.get(), 17764, "bbd");
        assert_eq!(super::ADVERSE_CONDITIONS.get(), 15110, "bfz");
        assert_eq!(super::ANCIENT_CORNUCOPIA.get(), 27775, "big");
        assert_eq!(super::AGATE_ASSAULT.get(), 28548, "blb");
